def kthMultipleOfAny(n, a, b, c):
    from math import gcd

    def lcm(u, v):
        return u // gcd(u, v) * v

    ab, bc, ac = lcm(a, b), lcm(b, c), lcm(a, c)
    abc = lcm(ab, c)

    def count(x):
        return x // a + x // b + x // c - x // ab - x // bc - x // ac + x // abc

    lo, hi = 1, 2 * 10 ** 9
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= n:
            hi = mid
        else:
            lo = mid + 1
    return lo
